import{_ as t,a as r,o as s,ai as i}from"./chunks/framework.BbOtTPsL.js";const h=JSON.parse('{"title":"Newsletter Subscribers","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/marketing/communications/subscribers/index.md","filePath":"api/graphql-api/admin/marketing/communications/subscribers/index.md","lastUpdated":1782473079000}'),a={name:"api/graphql-api/admin/marketing/communications/subscribers/index.md"};function o(n,e,d,c,l,m){return s(),r("div",null,e[0]||(e[0]=[i('<h1 id="newsletter-subscribers" tabindex="-1">Newsletter Subscribers <a class="header-anchor" href="#newsletter-subscribers" aria-label="Permalink to &quot;Newsletter Subscribers&quot;">​</a></h1><p>A <strong>newsletter subscriber</strong> is one email address signed up to receive the store&#39;s marketing emails. The list is the store&#39;s newsletter audience, and it mirrors the admin <strong>Marketing → Communications → Newsletter Subscribers</strong> screen.</p><h2 id="how-newsletter-subscribers-work" tabindex="-1">How newsletter subscribers work <a class="header-anchor" href="#how-newsletter-subscribers-work" aria-label="Permalink to &quot;How newsletter subscribers work&quot;">​</a></h2><p>Subscribers are <strong>created from the storefront</strong>, not from the admin API — a shopper opts in through the storefront newsletter form (double opt-in). The admin side exists to <strong>moderate</strong> that audience: list it, view a row, toggle a row&#39;s subscription state, or remove a row. There is no create operation and no mass-delete.</p><ul><li><strong><code>email</code></strong> — the subscribed address.</li><li><strong><code>isSubscribed</code></strong> — the subscription state. Toggling it switches the address on or off. When the address belongs to a registered customer, the same flag is mirrored onto that customer&#39;s newsletter preference, so the two stay in sync.</li><li><strong><code>channel</code></strong> — the storefront channel the subscriber opted in on, as a detail-only object (<code>{ id, _id, code, name }</code>); it is <code>null</code> on list rows.</li><li><strong><code>customerId</code> / <code>customerName</code></strong> — set when the subscriber&#39;s email matches a registered customer; <code>null</code> for a guest subscriber who signed up without an account.</li><li><strong>Delete</strong> — removes the row, first unsubscribing the linked customer (if any).</li></ul><p><strong>Relation to Campaigns.</strong> A <a href="/api/graphql-api/admin/marketing/communications/campaigns/">Campaign</a> sends an email template to the <strong>subscribed</strong> members of a customer group — so the subscriber list determines who actually receives a send.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/marketing/communications/subscribers-list.html">List</a></td><td><code>adminMarketingSubscribers</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/communications/subscribers-detail.html">Detail</a></td><td><code>adminMarketingSubscriber</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/communications/subscribers-toggle.html">Toggle</a></td><td><code>updateAdminMarketingSubscriber</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/communications/subscribers-delete.html">Delete</a></td><td><code>deleteAdminMarketingSubscriber</code> mutation</td></tr></tbody></table><p><code>customerId</code> and <code>customerName</code> resolve only when the subscriber&#39;s email matches a registered customer — they are <code>null</code> for guest subscribers.</p><p>All Newsletter Subscribers operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',10)]))}const b=t(a,[["render",o]]);export{h as __pageData,b as default};
